    AAMOTION_ENC_TYPE_ANALOG_SINE_COSINE = 4,
    /// Nikon 17 bit (future)
    AAMOTION_ENC_TYPE_NIKON17_BIT = 5,
    /// Absolute BiSS-C
    AAMOTION_ENC_TYPE_ABSOLUTE_BI_SSC = 6,
    /// Analog position feedback
    AAMOTION_ENC_TYPE_ANALOG_POSITION_FEEDBACK = 7,
    /// Tamagawa
    AAMOTION_ENC_TYPE_TAMAGAWA = 8
} aamotion_enc_type_t;

Enum aamotion_motion_mode_t (aamotion_enums.h; AAMotion C): Values of the MotionMode keyword (AAMOTION_KEYWORD_MOTION_MODE); aamotion_get_motion_mode_des describes a value. Mirrors the C# AAMotion.MotionMode.
Signature: typedef enum aamotion_motion_mode_t

Declaration:
typedef enum {
    /// Jog: The motor moves continuously at the speed set by Speed until a Stop command is
    /// received. Acceleration and deceleration are controlled by Accel and Decel, and can be
    /// smoothed by Jerk.
    AAMOTION_MOTION_MODE_JOG = 0,
    /// PTP: Point-to-point motion, moves to the position specified by RelTrgt or AbsTrgt (if
    /// RelTrgt=0, then AbsTrgt). Parameters are controlled by Accel, Speed, Decel, and Jerk.
    AAMOTION_MOTION_MODE_PTP = 1,
    /// PTP Repeat: Reciprocating motion between current and target position, waits RptWait time at
    /// each end, use StopRep to stop.
    AAMOTION_MOTION_MODE_PTPREPEAT = 2,
    /// Pulse/Direction Direct Mode: Position loop reference is directly from pulse/direction input.
    AAMOTION_MOTION_MODE_PULSE_DIR_DIRECT = 3,
    /// Pulse/Direction Indirect Mode: Pulses are accumulated to the target, the analyzer generates
    /// a smooth trajectory according to Accel, Decel, Speed, and Jerk.
    AAMOTION_MOTION_MODE_PULSE_DIR_INDIRECT = 4,
    /// Gear Direct Motion
    AAMOTION_MOTION_MODE_GEAR_DIRECT = 5,
    /// Gear Indirect Motion
    AAMOTION_MOTION_MODE_GEAR_INDIRECT = 6,
    /// ECAM Direct Motion
    AAMOTION_MOTION_MODE_ECAMDIRECT = 7,
    /// ECAM Indirect Motion
    AAMOTION_MOTION_MODE_ECAMINDIRECT = 8,
    /// FIFO Motion
    AAMOTION_MOTION_MODE_FIFOMOTION = 9,
    /// Follower Position Reference
    AAMOTION_MOTION_MODE_FOLLOWER_POSITION_REFERENCE = 10,
    /// CNC Group A Motion
    AAMOTION_MOTION_MODE_CNCGROUP_A = 11,
    /// Joystick Direct Motion (analog signal as position reference)
    AAMOTION_MOTION_MODE_JOYSTICK_DIRECT_POSITION = 12,
    /// Joystick Indirect Motion (analog signal as position reference, analyzer customizable)
    AAMOTION_MOTION_MODE_JOYSTICK_INDIRECT_POSITION = 13,
    /// Joystick Direct Motion (analog signal as speed reference)
    AAMOTION_MOTION_MODE_JOYSTICK_DIRECT_SPEED = 14,
    /// Joystick Indirect Motion (analog signal as speed reference, analyzer customizable)
    AAMOTION_MOTION_MODE_JOYSTICK_INDIRECT_SPEED = 15,
    /// Vector Motion
    AAMOTION_MOTION_MODE_VECTOR_MOTION = 16,
    /// CNC Group B Motion
    AAMOTION_MOTION_MODE_CNCGROUP_B = 17,
    /// Spline Buffer Motion
    AAMOTION_MOTION_MODE_SPLINE_BUFFER_MOTION = 18,
    /// FIFO Position Tracking: The axis follows the position targets pushed into its
    /// position-tracking FIFO, one every FIFOPosCycle samples, with the reference between targets
    /// interpolated as FIFOPosType sets.
    AAMOTION_MOTION_MODE_FIFOPOSITION_TRACKING = 19,
    /// Sine PTP: Single point-to-point motion on a sinusoidal acceleration profile (AXM sine
    /// planner), driven by Speed, Accel, Decel, JerkInAcc and JerkInDec, with an optional
    /// pre-cruise phase.
    AAMOTION_MOTION_MODE_SINE_PTP = 20,
    /// Sine PTP Repeat: Reciprocating motion on a sinusoidal acceleration profile, stopped with
    /// StopRep.
    AAMOTION_MOTION_MODE_SINE_PTPREPEAT = 21,
    /// PVAJ: The axis follows its PVAJList, one position, velocity, acceleration and jerk per
    /// point. Begin is refused until the list has passed PVAJValidate and PVAJArm is 1.
    AAMOTION_MOTION_MODE_PVAJ = 22,
    /// Multi-axis PVAJ: Begin starts every axis in this mode as one group, each on its own
    /// PVAJList, and is refused unless every member is armed, motor on and not in motion. Stop and
    /// Abort act on the whole group.
    AAMOTION_MOTION_MODE_MULTI_AXIS_PVAJ = 23
} aamotion_motion_mode_t;

Enum aamotion_map_type_t (aamotion_enums.h; AAMotion C): Values of the MapType keyword (AAMOTION_KEYWORD_MAP_TYPE); aamotion_get_map_type_des describes a value. Mirrors the C# AAMotion.MapType.
